import{_ as t,o,c as s,a3 as i}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Promotions and coupons","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/promotions.md","filePath":"dev/domain/promotions.md"}'),d={name:"dev/domain/promotions.md"};function a(n,e,r,c,l,p){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="promotions-and-coupons" tabindex="-1">Promotions and coupons <a class="header-anchor" href="#promotions-and-coupons" aria-label="Permalink to &quot;Promotions and coupons&quot;">​</a></h1><p>The <strong>Promotions</strong> module owns discounts: promotions, campaigns, coupons, the discount engine and the redemption ledger.</p><h2 id="the-model" tabindex="-1">The model <a class="header-anchor" href="#the-model" aria-label="Permalink to &quot;The model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Campaign</strong></td><td>A marketing umbrella that groups promotions and can be featured on the homepage</td></tr><tr><td><strong>Promotion</strong></td><td>A discount rule</td></tr><tr><td><strong>Coupon</strong></td><td>A code that unlocks a promotion that requires one</td></tr><tr><td><strong>Redemption</strong></td><td>An immutable ledger row per purchase and promotion</td></tr></tbody></table><h2 id="promotion-fields" tabindex="-1">Promotion fields <a class="header-anchor" href="#promotion-fields" aria-label="Permalink to &quot;Promotion fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Values</th></tr></thead><tbody><tr><td><code>scope</code></td><td><code>item</code> (per line) or <code>order</code> (the whole purchase)</td></tr><tr><td><code>discount_type</code></td><td><code>percentage</code> (basis points: 1250 = 12.5%), <code>fixed_amount</code>, <code>fixed_price</code></td></tr><tr><td><code>max_discount_amount</code></td><td>Cap on the discount across lines</td></tr><tr><td><code>min_subtotal_amount</code></td><td>Minimum spend; promotions with it are ignored for display prices</td></tr><tr><td><code>stacking</code></td><td><code>exclusive</code> or <code>stackable</code></td></tr><tr><td><code>funded_by</code></td><td><code>platform</code>, <code>center</code> or <code>shared</code> (with <code>center_share_bps</code>)</td></tr><tr><td><code>status</code></td><td><code>draft</code>, <code>active</code>, <code>paused</code>, <code>archived</code></td></tr><tr><td>Schedules</td><td>Optional weekly windows</td></tr><tr><td>Targets</td><td>Include or exclude targets</td></tr></tbody></table><h2 id="scope-and-funding" tabindex="-1">Scope and funding <a class="header-anchor" href="#scope-and-funding" aria-label="Permalink to &quot;Scope and funding&quot;">​</a></h2><p>Promotions apply only when a <strong>Client buys from a Center</strong>, and a center promotion never touches another center&#39;s lines. A promotion is <strong>live</strong> when it is active, <code>starts_at &lt;= now &lt; ends_at</code>, and its weekly schedule allows it.</p><p>The center API forces <code>center_id = route center</code> and <code>funded_by = center</code>. Only admins set funding, campaign or platform scope. Shared funding gives the center <code>intdiv(amount × center_share_bps, 10000)</code>.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>New promotions start as <strong>draft</strong>. Nothing returns to draft; <strong>archived</strong> is read-only. Once a promotion appears in <code>purchase_adjustments</code>, its scope, discount type and value, max discount and targets are <strong>frozen</strong>: archive it and create a new one to change them.</p><h2 id="how-discounts-combine" tabindex="-1">How discounts combine <a class="header-anchor" href="#how-discounts-combine" aria-label="Permalink to &quot;How discounts combine&quot;">​</a></h2><p><code>DiscountEngine</code> applies:</p><ul><li>At most <strong>one item offer per line</strong>: the largest amount, then the higher priority, then the lowest id.</li><li>At most <strong>one order offer</strong>.</li><li>An <strong>exclusive item winner</strong> blocks non-exclusive order offers. An <strong>exclusive order offer</strong> replaces item discounts only if it is larger. Stackable order offers apply after item discounts.</li><li>A line discount never exceeds its subtotal. <code>max_discount_amount</code> caps a promotion across lines.</li><li>Order discounts are split across lines by <strong>largest remainder</strong>, so they add up exactly.</li></ul><h2 id="coupons" tabindex="-1">Coupons <a class="header-anchor" href="#coupons" aria-label="Permalink to &quot;Coupons&quot;">​</a></h2><p>Checks run in the fixed order of <code>PromotionResolverService</code>. Failures that would reveal whether a code exists all report <code>invalid</code>. The coupon&#39;s promotion <strong>competes with automatic offers</strong> and returns <code>coupon_not_better</code> if it loses. Checkout throws <code>CouponRejectedException</code> for a coupon that was sent but not applied. A coupon&#39;s per-client limit overrides the promotion&#39;s. Codes are stored trimmed and upper-cased.</p><h2 id="usage-is-consumed-only-at-purchase" tabindex="-1">Usage is consumed only at purchase <a class="header-anchor" href="#usage-is-consumed-only-at-purchase" aria-label="Permalink to &quot;Usage is consumed only at purchase&quot;">​</a></h2><p>Quotes and display prices <strong>never reserve usage</strong>. <code>RedemptionService</code> consumes usage with conditional atomic increments inside the purchase transaction, locking promotions, then coupons, then per-client rows in id order; zero affected rows fails closed. Release at most once, on cancel or full refund. The redemption ledger is the source of truth (<code>promotions:reconcile</code> reports drift). <code>PriceChangedException</code> is thrown if <code>expected_total_amount</code> differs. Writes flush the promotions cache version.</p><h2 id="display-prices" tabindex="-1">Display prices <a class="header-anchor" href="#display-prices" aria-label="Permalink to &quot;Display prices&quot;">​</a></h2><p><code>ServicePriceDisplay::forServices($services, $at)</code> returns the discounted &quot;from&quot; price for services that carry a <code>start_price</code>:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">serviceId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;original&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 15000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;discounted&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12750</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;discount_amount&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2250</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;badge&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;-15%&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span></code></pre></div><p>It applies the center&#39;s live <strong>automatic item</strong> offers to one unit at the start price. Offers with a minimum spend or order scope depend on the whole purchase and are ignored. Services with no applicable offer are omitted.</p><p>Used by: homepage curated services, <code>clients/offers/{promotion}</code>, center details services and service details (<code>display_price</code>).</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Endpoints</th></tr></thead><tbody><tr><td>Client</td><td><code>clients/offers</code>, <code>clients/offers/{promotion}</code></td></tr><tr><td>Center</td><td><code>centers/{center}/promotions</code> CRUD, <code>activate</code>, <code>pause</code>, <code>archive</code>, <code>schedules</code>, <code>targets</code>, <code>coupons</code>, <code>coupons/generate</code>, <code>redemptions</code></td></tr><tr><td>Admin</td><td>The same under <code>admin/promotions</code>, plus <code>campaigns</code> and coupon assignments</td></tr></tbody></table>',25)])])}const m=t(d,[["render",a]]);export{u as __pageData,m as default};
